import{_ as a,o as t,c as r,a7 as o}from"./chunks/framework.FWlv_suP.js";const u=JSON.parse('{"title":"Card Nest Data Deletion","description":"Standalone instructions for deleting Card Nest data.","frontmatter":{"title":"Card Nest Data Deletion","description":"Standalone instructions for deleting Card Nest data.","navbar":false,"sidebar":false,"aside":false,"outline":false,"footer":false,"prev":false,"next":false,"editLink":false,"lastUpdated":false,"pageClass":"standalone-policy"},"headers":[],"relativePath":"data-deletion/card-nest.md","filePath":"data-deletion/card-nest.md"}'),s={name:"data-deletion/card-nest.md"};function d(n,e,i,l,c,p){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="delete-card-nest-data" tabindex="-1">Delete Card Nest Data <a class="header-anchor" href="#delete-card-nest-data" aria-label="Permalink to &quot;Delete Card Nest Data&quot;">​</a></h1><p>Card Nest has no online account or developer-operated cloud database. Its app data is stored on your device.</p><h2 id="delete-individual-records" tabindex="-1">Delete individual records <a class="header-anchor" href="#delete-individual-records" aria-label="Permalink to &quot;Delete individual records&quot;">​</a></h2><p>Cards, transactions, categories, loans, EMIs, receipt attachments, and related records can be deleted from their corresponding app screens. Some deletions can also update linked balances or related records.</p><h2 id="delete-older-transaction-history" tabindex="-1">Delete older transaction history <a class="header-anchor" href="#delete-older-transaction-history" aria-label="Permalink to &quot;Delete older transaction history&quot;">​</a></h2><p>Open <strong>Settings → Backup &amp; data</strong>, choose a 3, 5, 7, or 10-year retention period, and select <strong>Clean older data</strong>. Review and confirm the deletion.</p><h2 id="delete-all-card-nest-data" tabindex="-1">Delete all Card Nest data <a class="header-anchor" href="#delete-all-card-nest-data" aria-label="Permalink to &quot;Delete all Card Nest data&quot;">​</a></h2><p>Open <strong>Settings → Backup &amp; data → Delete all data</strong>, review the warning, and confirm. If an application PIN exists, authorize the action using the PIN or an enabled Android biometric. This removes the Card Nest database and settings stored by the app. It also disables SMS Sync and clears its app-private, encrypted SMS review queue and SMS Sync settings.</p><p>Turning off SMS Sync stops future SMS discovery and scheduling, but does not revoke Android&#39;s SMS permission or remove transactions you have already approved. Revoke the permission from Android system settings if you no longer want Card Nest to access SMS. You can also use the app&#39;s retention controls to remove older extracted SMS review data while preserving minimal deduplication records that prevent an already handled message from being imported again.</p><p>You can also clear Card Nest storage from Android system settings or uninstall the app.</p><h2 id="delete-files-outside-the-app" tabindex="-1">Delete files outside the app <a class="header-anchor" href="#delete-files-outside-the-app" aria-label="Permalink to &quot;Delete files outside the app&quot;">​</a></h2><p>Deleting app data does not remove <code>.cnbak</code> backups, CSV files, PDF reports, or copies shared with another app or storage provider. Delete those files separately from every destination.</p><p>Because the developer does not hold Card Nest account data, emailing support cannot delete records stored on your device.</p>',13)])])}const f=a(s,[["render",d]]);export{u as __pageData,f as default};
